<?php $hubPath='/web-admin/cloud/site/'.$site['id'];$canEdit=in_array('update',$site['permissions'],true);$canPublish=in_array('publish',$site['permissions'],true);$canManage=in_array('settings',$site['permissions'],true); ?>
<div class="topline"><a href="/web-admin/cloud">CLOUD GATEWAY</a><span><?= e($site['render_mode']) ?> rendering</span></div><header class="page-header"><div><span class="website-kicker">SCHEMA-DRIVEN CLOUD STUDIO</span><h1><?= e($site['name']) ?></h1><p class="muted"><?= e($site['url']) ?></p></div><a class="btn secondary" href="<?= $hubPath ?><?= $page?'?page='.e($page['slug']):'' ?>">Refresh status</a></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<div class="studio-scope"><span class="studio-scope-dot"></span><strong>Cloud source of truth</strong><span>Saving creates a draft. Publishing updates the content API and queues site delivery.</span></div>
<button class="secondary studio-mobile-nav" type="button" data-studio-nav aria-expanded="false" aria-controls="studio-navigation">Browse cloud pages</button><div class="studio-layout"><aside id="studio-navigation" class="card studio-nav"><a class="studio-nav-home" href="/web-admin/cloud">← All sites</a><div class="studio-nav-group"><h2>Pages</h2><?php foreach($manifest['pages']??[] as $item): ?><a href="<?= $hubPath ?>?page=<?= e($item['slug']) ?>" <?= ($page['slug']??'')===$item['slug']?'class="selected" aria-current="page"':'' ?>><?= e($item['label']) ?></a><?php endforeach; ?></div><div class="studio-nav-group"><h2>Manage</h2><a href="#hub-media">Media library</a><a href="#hub-versions">Versions &amp; rollback</a><a href="#hub-deliveries">Publish delivery</a><a href="#hub-health">Site health</a><a href="#hub-audit">Audit log</a></div></aside><div class="studio-main">
<?php if(!$page): ?><section class="card studio-empty"><h2>No manifest registered yet.</h2><p class="muted">Use the connector’s register call to declare this site’s editable pages and fields.</p></section><?php else: ?>
<section class="card studio-editor" id="hub-editor"><div class="section-heading"><div><span class="website-kicker"><?= e($page['slug']) ?></span><h2><?= e($definition['label']) ?></h2></div><span class="badge"><?= e(ucfirst($page['status'])) ?> · v<?= $page['version'] ?></span></div><form class="form-grid" method="post" action="<?= $hubPath ?>/save"><?= csrf_field() ?><input type="hidden" name="page" value="<?= e($page['slug']) ?>"><input type="hidden" name="version" value="<?= $page['version'] ?>">
<?php foreach($definition['fields'] as $field):$key=$field['key'];$value=$page['fields'][$key]??'';$long=in_array($field['type'],['textarea','richtext'],true); ?><label class="<?= $long?'full':'' ?>"><?= e($field['label']) ?><?= $field['required']?' *':'' ?><?php if($long): ?><textarea name="fields[<?= e($key) ?>]" rows="<?= $field['type']==='richtext'?8:3 ?>" maxlength="<?= $field['max_length'] ?>" <?= $field['required']?'required':'' ?> <?= !$canEdit?'readonly':'' ?>><?= e($value) ?></textarea><?php elseif($field['type']==='boolean'): ?><input type="hidden" name="fields[<?= e($key) ?>]" value="0"><input name="fields[<?= e($key) ?>]" type="checkbox" value="1" <?= $value?'checked':'' ?> <?= !$canEdit?'disabled':'' ?>><?php else: ?><input name="fields[<?= e($key) ?>]" type="<?= e(match($field['type']){'number'=>'number','image','url'=>'url','date'=>'date',default=>'text'}) ?>" value="<?= e($value) ?>" maxlength="<?= $field['max_length'] ?>" <?= $field['type']==='number'?'step="any"':'' ?> <?= $field['required']?'required':'' ?> <?= !$canEdit?'readonly':'' ?>><?php if($field['type']==='image'&&$media): ?><select data-hub-media-target="fields[<?= e($key) ?>]" <?= !$canEdit?'disabled':'' ?>><option value="">Choose from cloud media</option><?php foreach($media as $file):if(!str_starts_with($file['mime'],'image/'))continue; ?><option value="<?= e($file['url']) ?>"><?= e($file['filename']) ?></option><?php endforeach; ?></select><?php endif; endif; ?></label><?php endforeach; ?><?php if($canEdit): ?><div class="full studio-form-footer"><button>Save cloud draft</button><span class="footnote">Drafts stay private until an authorised publisher approves them.</span></div><?php endif; ?></form></section>
<section class="card"><div class="section-heading"><div><h2>Publish this version</h2><p class="muted">Current draft v<?= $page['version'] ?> · Published <?= $page['published_version']===null?'Never':'v'.e($page['published_version']) ?></p></div><?php if($canPublish): ?><form method="post" action="<?= $hubPath ?>/publish" data-confirm="Publish this exact draft version to the content API and queue its site delivery?"><?= csrf_field() ?><input type="hidden" name="page" value="<?= e($page['slug']) ?>"><input type="hidden" name="version" value="<?= $page['version'] ?>"><button <?= $page['published_version']!==null&&(int)$page['published_version']===$page['version']?'disabled':'' ?>>Publish approved version</button></form><?php else: ?><span class="badge">Provider approval required</span><?php endif; ?></div><details><summary>Preview saved draft</summary><dl class="website-record-values"><?php foreach($definition['fields'] as $field):$value=$page['fields'][$field['key']]??''; ?><div><dt><?= e($field['label']) ?></dt><dd><?= e(is_bool($value)?($value?'Yes':'No'):$value) ?></dd></div><?php endforeach; ?></dl><p class="footnote">This is the saved draft, not an unsaved form or a live website preview. Rich text is displayed safely as source text.</p></details><p class="footnote">Public website: <span><?= e($site['url']) ?></span></p><button class="secondary" type="button" data-hub-copy-value="<?= e($site['url']) ?>">Copy website URL</button><span class="footnote" data-hub-copy-status aria-live="polite"></span></section><?php endif; ?>
<section class="card" id="hub-media"><div class="section-heading"><h2>Cloud media library</h2><span class="badge"><?= count($media) ?> recent files</span></div><?php if($canEdit): ?><form class="studio-upload" method="post" enctype="multipart/form-data" action="<?= $hubPath ?>/media" hx-boost="false"><?= csrf_field() ?><label>Upload media<input type="file" name="file" accept="image/jpeg,image/png,image/webp,image/gif,application/pdf,video/mp4" required></label><button>Upload to cloud</button></form><p class="footnote">Up to 5 MB. Media becomes public only when referenced by a published page.</p><?php endif; ?><?php if(!$media): ?><p class="muted">No cloud media uploaded yet.</p><?php else: foreach($media as $file): ?><article class="studio-record-row"><div><strong><?= e($file['filename']) ?></strong><p class="muted"><?= number_format($file['bytes']/1024,1) ?> KB · <?= e($file['mime']) ?></p></div><button class="secondary" type="button" data-hub-copy-value="<?= e($file['url']) ?>">Copy media URL</button></article><?php endforeach; ?><span class="footnote" data-hub-copy-status aria-live="polite"></span><?php endif; ?></section>
<section class="card" id="hub-versions"><h2>Version history &amp; rollback</h2><?php if(!$versions): ?><p class="muted">Saved drafts and publications will appear here.</p><?php else: foreach($versions as $version): ?><article class="studio-record-row"><div><strong>v<?= e($version['version']) ?> · <?= e(ucfirst($version['stage'])) ?></strong><p class="muted"><?= e($version['actor']) ?> · <?= e($version['created_at']) ?></p></div><?php if($canPublish&&$page&&$version['stage']==='published'&&(int)$version['version']!==$page['version']): ?><form method="post" action="<?= $hubPath ?>/rollback" data-confirm="Publish this earlier content as a new version? Existing history will be preserved."><?= csrf_field() ?><input type="hidden" name="page" value="<?= e($page['slug']) ?>"><input type="hidden" name="version" value="<?= $page['version'] ?>"><input type="hidden" name="target_version" value="<?= e($version['version']) ?>"><button class="secondary">Rollback to v<?= e($version['version']) ?></button></form><?php endif; ?></article><?php endforeach; endif; ?></section>
<section class="card" id="hub-deliveries"><div class="section-heading"><h2>Publish delivery</h2><a href="<?= $hubPath ?><?= $page?'?page='.e($page['slug']):'' ?>#hub-deliveries">Refresh</a></div><?php if(!$jobs): ?><p class="muted">No publications queued yet.</p><?php else: foreach($jobs as $job): ?><article class="studio-record-row"><div><strong><?= e($job['page']) ?> · v<?= e($job['version']) ?></strong><p class="muted">Webhook: <?= e($job['delivery']) ?> · <?= e($job['attempts']) ?> attempts</p><?php if($job['last_error']): ?><p class="muted"><?= e($job['last_error']) ?></p><?php endif; ?></div><span class="badge hub-status-<?= e($job['status']) ?>"><?= e(ucfirst($job['status'])) ?></span></article><?php endforeach; endif; ?><p class="footnote">A queued job is processed by your cloud worker. Accepting a webhook does not prove the site is live; a connector acknowledgement or matching rendered version does.</p></section>
<section class="card" id="hub-health"><div class="section-heading"><h2>Site health</h2><?php if($canManage): ?><form method="post" action="<?= $hubPath ?>/health"><?= csrf_field() ?><button class="secondary">Check now</button></form><?php endif; ?></div><?php if(!$health['checks']): ?><p class="muted">No health samples recorded. No uptime percentage is estimated.</p><?php else:$latest=$health['checks'][0]; ?><dl class="website-record-values"><div><dt>Latest HTTP status</dt><dd><?= e($latest['http_status']??'Unreachable') ?></dd></div><div><dt>Response time</dt><dd><?= $latest['latency_ms']===null?'Not measured':e($latest['latency_ms']).' ms' ?></dd></div><div><dt>Sample uptime</dt><dd><?= e($health['uptime_percent']) ?>% across <?= count($health['checks']) ?> checks</dd></div><div><dt>SSL expiry</dt><dd><?= e($latest['ssl_expires']??'Not reported by TLS runtime') ?></dd></div><div><dt>Domain renewal</dt><dd><?= e($health['domain_expires']??'Not recorded') ?></dd></div><div><dt>Checked</dt><dd><?= e($latest['checked_at']) ?></dd></div></dl><?php if($latest['error']): ?><p><?= e($latest['error']) ?></p><?php endif; endif; ?></section>
<section class="card" id="hub-audit"><h2>Audit log</h2><?php if(!$audit): ?><p class="muted">No actions recorded for this site yet.</p><?php else: foreach(array_slice($audit,0,25) as $entry): ?><article class="studio-activity"><span class="studio-activity-mark"><?= icon('check') ?></span><div><strong><?= e($entry['action']) ?></strong><p><?= e($entry['actor']) ?> · <?= e($entry['resource']) ?></p></div><time><?= e($entry['created_at']) ?></time></article><?php endforeach; endif; ?></section>
</div></div>
